import java.sql.*;
public class JdbcTasks {
    public String findUserEmail(Connection conn, int userId) throws SQLException {
        PreparedStatement ps = conn.prepareStatement(
            "SELECT email FROM users WHERE id = ?");
        ps.setInt(1, userId);
        ResultSet rs = ps.executeQuery();
        if (rs.next()) {
            String email = rs.getString("email");
            rs.close();
            ps.close();
            return email;
        }
        rs.close();
        ps.close();
        return null;
    }
}

